  /// Referrer URL that led to the session initiation.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime

  /// Timestamp when the session expired or will expire (null if active).
  expired_at DateTime?

  //----
  // RELATIONS
  //----
  member discussion_board_member @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@index([discussion_board_member_id, created_at], map: "discussion_board_member_sessions_discussion_board_memb_336fc309")
